// Mapping catalog browser. The SAME index.json feeds this page and the
// in-app mapping browser — one catalog, two frontends. The index is
// regenerated by CI in the talea-mappings repo on every merge.
//
// index.json schema (v1):
// {
//   "version": 1,
//   "mappings": [
//     {
//       "id": "pioneer-ddj-400",          // unique, kebab-case
//       "name": "Pioneer DDJ-400",         // display name
//       "manufacturer": "Pioneer DJ",
//       "controller": "DDJ-400",
//       "author": "…",
//       "description": "…",
//       "version": "1.0.0",
//       "file": "mappings/pioneer/ddj-400.json"  // repo-relative
//     }
//   ]
// }

const MAPPINGS_REPO = "eeeurico/talea-mappings";
const INDEX_URL = `https://raw.githubusercontent.com/${MAPPINGS_REPO}/main/index.json`;
const RAW_BASE = `https://raw.githubusercontent.com/${MAPPINGS_REPO}/main/`;

const list = document.getElementById("map-list");
const search = document.getElementById("map-search");

let all = [];

function render(mappings) {
  if (!list) return;
  if (mappings.length === 0) {
    list.innerHTML = `
      <div class="map-empty">
        No mappings match.
      </div>`;
    return;
  }
  list.innerHTML = mappings
    .map(
      (m) => `
      <div class="map-row">
        <div class="info">
          <div class="name">${escapeHtml(m.name)}</div>
          <div class="detail">${escapeHtml(m.description || "")}</div>
        </div>
        <div class="meta">
          v${escapeHtml(m.version || "1.0")}<br />${escapeHtml(m.author || "")}
        </div>
        <a class="btn" href="${RAW_BASE}${encodeURI(m.file)}" download>Download</a>
      </div>`,
    )
    .join("");
}

function escapeHtml(s) {
  return String(s).replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
  );
}

function applySearch() {
  const q = (search?.value || "").trim().toLowerCase();
  if (!q) {
    render(all);
    return;
  }
  render(
    all.filter((m) =>
      [m.name, m.manufacturer, m.controller, m.author]
        .filter(Boolean)
        .some((f) => f.toLowerCase().includes(q)),
    ),
  );
}

async function load() {
  try {
    const res = await fetch(INDEX_URL);
    if (!res.ok) throw new Error(`catalog unavailable (${res.status})`);
    const index = await res.json();
    all = Array.isArray(index.mappings) ? index.mappings : [];
    if (all.length === 0) throw new Error("catalog empty");
    render(all);
  } catch {
    if (list) {
      list.innerHTML = `
        <div class="map-empty">
          The community catalog is just getting started.<br />
          The app ships with the <strong>Pioneer DDJ-400</strong> mapping built in.
          <div class="mono">catalog: github.com/${MAPPINGS_REPO}</div>
        </div>`;
    }
  }
}

search?.addEventListener("input", applySearch);
load();
